{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of the plan — are we minimizing the number of containers used, minimizing total transportation cost, or maximizing the total amount of goods shipped?"
  ],
  "rationale": "The response asks for a single policy choice (the optimization objective) by presenting mutually exclusive options, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all available goods have to be shipped, or is it acceptable to leave some goods unshipped (i.e., the per-type totals across containers can be less than or equal to the available quantities)?"
  ],
  "rationale": "The response asks a single clarification question regarding whether goods must be fully shipped or if partial shipping is allowed."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a fixed, known number of containers available to choose from (so the model picks which ones to use), or is the number of containers unlimited and the model simply decides how many to use?"
  ],
  "rationale": "The response asks a single clarification question regarding the constraint on the number of containers (fixed vs. unlimited)."
}

{
  "action": "question",
