  "atomic_questions": [
    "Are the goods units indivisible (each type must be loaded in whole units per container), or can they be split fractionally?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of goods units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a maximum number of units of any single goods type that can fit in one container (a per-type per-container limit), or is the only per-container limit the total weight of 60 tons?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive constraints, so it counts as one independent question."
}

